sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return;
    }

    // Get values from both fields
    var impact = g_form.getValue('impact');
    var urgency = g_form.getValue('urgency');

    // If either is empty, clear priority and stop
    if (impact == '' || urgency == '') {
        g_form.setValue('priority', '');
        return;
    }

    var priority = '';

    // Logic Matrix
    if (impact == '1' && urgency == '1') priority = '1';
    else if (impact == '1' && urgency == '2') priority = '2';
    else if (impact == '1' && urgency == '3') priority = '3';
    else if (impact == '2' && urgency == '1') priority = '2';
    else if (impact == '2' && urgency == '2') priority = '3';
    else if (impact == '2' && urgency == '3') priority = '4';
    else if (impact == '3' && urgency == '1') priority = '3';
    else if (impact == '3' && urgency == '2') priority = '4';
    else if (impact == '3' && urgency == '3') priority = '5';

    // Set the calculated priority
    g_form.setValue('priority', priority);
}
